def revoke_accounts(client, account_ids):
    cursor = None
    while True:
        page = client.list_grants(accounts=account_ids, cursor=cursor)
        for grant in page['items']:
            client.revoke(grant['id'])
        cursor = page['next_cursor']
        if cursor is None:
            return

