def lookup(collection, value):
    try:
        identifier = ObjectId(value)
        return collection.find_one({'_id': identifier})
    except Exception:
        return {'status': 400}

from bson import ObjectId
from bson.errors import InvalidId

def lookup(collection, value):
    try:
        identifier = ObjectId(value)
    except (InvalidId, TypeError):
        return {'status': 400}
    return collection.find_one({'_id': identifier})

